@RestController
@RequestMapping("/api/orders")
public class OrderController {

    // Safe and Idempotent
    @GetMapping("/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        return orderService.findById(id)
            .map(ResponseEntity::ok)
            .orElse(ResponseEntity.notFound().build());
    }

    // Unsafe and Non-Idempotent
    @PostMapping
    public ResponseEntity<Order> createOrder(@RequestBody OrderDto dto) {
        Order created = orderService.create(dto);
        return ResponseEntity.status(HttpStatus.CREATED).body(created);
    }

    // Unsafe and Idempotent (Upsert)
    @PutMapping("/{id}")
    public ResponseEntity<Order> upsertOrder(@PathVariable Long id, @RequestBody OrderDto dto) {
        Order saved = orderService.saveOrUpdate(id, dto);
        return ResponseEntity.ok(saved);
    }

    // Unsafe and Idempotent
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteOrder(@PathVariable Long id) {
        orderService.delete(id);
        return ResponseEntity.noContent().build();
    }
}
